SELECT *, ROW_NUMBER() OVER w_recent seq_no, ROW_NUMBER() OVER w_recent row_seq, FIRST_VALUE(country) IGNORE NULLS OVER w_hist first_known_country, ROW_NUMBER() OVER w_part seq_no_2 FROM sessions WHERE country IN ('DE', 'JP', 'US') WINDOW w_recent AS (PARTITION BY device ORDER BY started_at DESC, id), w_hist AS (ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_part AS (PARTITION BY customer_id ORDER BY started_at, id);
